WITH rpt_tickets AS (
SELECT src.id, src.ticket_number, src.subject, src.description, src.status, src.priority, src.channel, src.category, src.skill, src.customer_id, src.customer_name, src.customer_email, src.customer_phone, src.assignee_id, src.assignee_name, src.resolver_id, src.resolver_name, src.queue_id, src.queue_name, src.created_by_id, src.created_by_name, src.due_at, src.first_response_at, src.resolved_at, src.csat_score, src.csat_rated_at, src.csat_comment, src.ai_summary, src.created_at, src.updated_at FROM (
SELECT * FROM ticketing.tickets WHERE organization_id = %(_org_id)s
) src WHERE TRUE
)
SELECT csat_score FROM rpt_tickets AS tickets WHERE ticket_number = '7150' OR ticket_number = '#7150' LIMIT 50

